import { connect, kea, path, selectors } from 'kea'
import { MakeLogicType } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { externalDataDestinationsList } from 'products/warehouse_sources/frontend/generated/api'
import { ExternalDataDestinationApi } from 'products/warehouse_sources/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationLookupLogicValues {
    currentTeamId: number | null // teamLogic
    destinations: ExternalDataDestinationApi[]
    destinationsById: Record<string, ExternalDataDestinationApi>
    destinationsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationLookupLogicActions {
    loadDestinations: () => any
    loadDestinationsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDestinationsSuccess: (
        destinations: ExternalDataDestinationApi[],
        payload?: any
    ) => {
        destinations: ExternalDataDestinationApi[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface destinationLookupLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        destinationsById: (destinations: any) => Record<string, ExternalDataDestinationApi>
    }
}

export type destinationLookupLogicType = MakeLogicType<
    destinationLookupLogicValues,
    destinationLookupLogicActions,
    Record<string, any>,
    destinationLookupLogicMeta
>

/**
 * Every destination the project has, keyed by id.
 *
 * A run records only destination ids, so any surface naming a run's destinations needs the rows
 * to go with them. One mounted logic serves them all rather than each list fetching its own.
 */
export const destinationLookupLogic = kea<destinationLookupLogicType>([
    path(['products', 'data_warehouse', 'shared', 'destinationLookupLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        destinations: [
            [] as ExternalDataDestinationApi[],
            {
                loadDestinations: async () => {
                    const response = await externalDataDestinationsList(String(values.currentTeamId))
                    return response.results ?? []
                },
            },
        ],
    })),
    selectors({
        destinationsById: [
            (s: any) => [s.destinations],
            (destinations: ExternalDataDestinationApi[]): Record<string, ExternalDataDestinationApi> =>
                Object.fromEntries(destinations.map((destination) => [destination.id, destination])),
        ],
    }),
])
